import type { Register } from 'claude-code'

import type { Leituras } from '../types'

// Tudo vive dentro de register: o módulo é copiado sozinho para cada
// projeto e também carregado assim pelos testes do ativador.
export const register: Register = on => {
  const TURNOS_NO_GRAFICO = 12
  const VAZIO: Leituras = { tokens: [], janela: 0 }

  // Símbolos de largura simples e sem apresentação de emoji: alinham em
  // qualquer fonte monoespaçada, no bash, no PowerShell, no Linux e no Windows.
  const CLIMAS = [
    { ate: 25, simbolo: '☼', frase: 'Céu limpo', cor: 'yellow' },
    { ate: 49, simbolo: '☁', frase: 'Céu nublado com nuvens', cor: 'cyan' },
    { ate: 74, simbolo: '☂', frase: 'Chuva', cor: 'blue' },
    { ate: 89, simbolo: '↯', frase: 'Tempestade de raios com ventos fortes!!!', cor: 'magenta' },
    { ate: 100, simbolo: '☈☈☈☈☈', frase: 'DILÚVIO !!! Limpa esse contexto ai !!!', cor: 'red' },
  ]
  const BARRAS = ['▁', '▂', '▃', '▄', '▅', '▆', '▇', '█']

  const percentualDe = (tokens: number, janela: number) =>
    janela > 0 ? Math.min(100, Math.max(0, Math.round((tokens * 100) / janela))) : 0

  const DILUVIO = CLIMAS[CLIMAS.length - 1]!
  const climaPara = (percentual: number) =>
    CLIMAS.find(clima => percentual <= clima.ate) ?? DILUVIO

  // 800 -> "800", 135000 -> "135k", 1200000 -> "1,2M"
  const tokensCurtos = (tokens: number) => {
    const n = Math.abs(tokens)
    if (n < 1000) return String(Math.round(n))
    if (n < 999_500) return `${Math.round(n / 1000)}k`
    return `${(Math.round(n / 100_000) / 10).toString().replace('.', ',')}M`
  }

  // Uma barra por turno, na altura do preenchimento da janela naquele turno.
  const barra = (tokens: number, janela: number) => {
    const fracao = janela > 0 ? Math.min(1, Math.max(0, tokens / janela)) : 0
    return BARRAS[Math.min(BARRAS.length - 1, Math.floor(fracao * BARRAS.length))] ?? '▁'
  }

  // Uma leitura por turno: o engine mede a sessão ao fim de cada turno.
  on('session.measure', async ($, e, next) => {
    const { tokens, window: janela } = e.context
    if (e.changed.includes('context') && tokens !== undefined) {
      const { value: atual = VAZIO } = await $.state.get({
        plugin: 'monitor-do-contexto-local',
        key: 'leituras',
      })
      await $.state.set(
        { plugin: 'monitor-do-contexto-local', key: 'leituras' },
        { tokens: [...atual.tokens, tokens].slice(-TURNOS_NO_GRAFICO), janela },
      )
    }
    return next(e)
  })

  on('session.end', async ($, e, next) => {
    if (e.reason === 'clear') {
      await $.state.set({ plugin: 'monitor-do-contexto-local', key: 'leituras' }, VAZIO)
    }
    return next(e)
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (e.props.hasSurvey) return next(e)

    const { value: { tokens, janela } = VAZIO } = await $.state.get({
      plugin: 'monitor-do-contexto-local',
      key: 'leituras',
    })
    const { Box, Text } = $.ui.resolve(e)

    if (tokens.length === 0 || janela <= 0) {
      return (
        <Box>
          <Text dimColor wrap="truncate-end">
            ☼ Previsão do contexto: aguardando o primeiro turno
          </Text>
        </Box>
      )
    }

    const usados = tokens.at(-1) ?? 0
    const anterior = tokens.at(-2) ?? 0
    const diferenca = usados - anterior
    const percentual = percentualDe(usados, janela)
    const clima = climaPara(percentual)

    return (
      <Box>
        <Text wrap="truncate-end">
          <Text color={clima.cor} bold>
            {clima.simbolo} {clima.frase}
          </Text>
          <Text dimColor> · </Text>
          <Text color={clima.cor}>{percentual}%</Text>
          <Text>
            {' '}
            {tokensCurtos(usados)} / {tokensCurtos(janela)}
          </Text>
          <Text dimColor> · </Text>
          <Text dimColor>{'·'.repeat(TURNOS_NO_GRAFICO - tokens.length)}</Text>
          {tokens.map((t, i) => (
            <Text key={String(i)} color={climaPara(percentualDe(t, janela)).cor}>
              {barra(t, janela)}
            </Text>
          ))}
          <Text dimColor> · </Text>
          <Text>
            {diferenca < 0 ? '−' : '+'}
            {tokensCurtos(diferenca)} no último turno
          </Text>
        </Text>
      </Box>
    )
  })
}

